import html

def esc(value): return html.escape(str(value), quote=True)
STYLE = '''
:root{color-scheme:light;--ink:#172a35;--muted:#687b86;--line:#dde5e8;--accent:#087f75}*{box-sizing:border-box}body{margin:0;background:#f4f7f8;color:var(--ink);font:16px/1.6 system-ui,sans-serif}a{color:var(--accent);text-decoration:none}a:hover{text-decoration:underline}header{background:#fff;border-bottom:1px solid var(--line)}.bar{max-width:1200px;margin:auto;padding:20px 28px;display:flex;align-items:center;justify-content:space-between;gap:20px}.brand{color:var(--ink);font-size:23px;font-weight:850;letter-spacing:-1px}.brand b{background:var(--accent);color:white;padding:5px 9px;border-radius:9px;margin-right:9px}nav{display:flex;align-items:center;gap:24px}main{max-width:1200px;margin:44px auto;padding:0 28px}h1{font-size:clamp(30px,4vw,46px);line-height:1.15;letter-spacing:-1.5px;margin:12px 0 18px}h2{font-size:21px;line-height:1.4;letter-spacing:-.4px}.eyebrow,.tag{font-size:12px;text-transform:uppercase;letter-spacing:1.5px;font-weight:750;color:var(--accent)}.intro{color:var(--muted);max-width:650px}.filters{display:grid;grid-template-columns:2fr 1fr 1fr auto;gap:14px;background:white;border:1px solid var(--line);padding:22px;border-radius:16px;margin:30px 0}label{display:block;font-size:13px;font-weight:650}input,select{font:inherit;width:100%;padding:11px 13px;border:1px solid #bdcdd3;border-radius:8px;background:white;color:var(--ink);margin-top:6px}button,.button{font:inherit;font-weight:650;background:var(--accent);color:white;border:0;padding:12px 20px;border-radius:8px;cursor:pointer;display:inline-block}button:hover,.button:hover{background:#06685f;text-decoration:none}.filters button{align-self:end}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}article{background:white;border:1px solid var(--line);border-radius:14px;padding:26px;display:flex;flex-direction:column}article h2 a{color:var(--ink)}article p{color:var(--muted)}.meta,small{font-size:13px;color:var(--muted)}.cardfoot{margin-top:auto;padding-top:18px;border-top:1px solid var(--line);display:flex;justify-content:space-between;gap:10px}.results{display:flex;justify-content:space-between;margin:24px 0}.empty{grid-column:1/-1;text-align:center;padding:55px;border:1px dashed #bdcdd3;border-radius:14px}.auth{max-width:460px;margin:50px auto;background:white;border:1px solid var(--line);border-radius:18px;padding:32px}.auth h1{font-size:30px}.auth label{margin:18px 0}.auth button{width:100%;margin-top:8px}.notice{background:#e5f4ef;border:1px solid #b3dacc;padding:14px;border-radius:9px}.error{background:#fff0ed;border-color:#ecc6bb}.reading{max-width:800px;margin:auto}.reading h1{font-size:36px}.reading p{white-space:pre-line}footer{max-width:1200px;margin:70px auto 0;padding:24px 28px;border-top:1px solid var(--line);color:var(--muted);font-size:13px}.logout{display:inline}.logout button{padding:6px 10px;font-size:13px;background:#e7f2f0;color:var(--accent)}:focus-visible{outline:3px solid #e6ad47;outline-offset:3px}@media(max-width:900px){.cards{grid-template-columns:repeat(2,minmax(0,1fr))}.filters{grid-template-columns:1fr 1fr}}@media(max-width:600px){.bar{padding:16px;align-items:flex-start}nav{gap:12px;flex-wrap:wrap;justify-content:flex-end;font-size:13px}main{padding:0 16px;margin-top:28px}.cards,.filters{grid-template-columns:1fr}.auth{padding:24px}.brand{white-space:nowrap;font-size:20px}.reading h1{font-size:29px}}
'''
def page(content,title='News',user=None,csrf=''):
    account = f'<span class="meta">{esc(user["email"])}</span><form class="logout" action="/logout" method="post"><input type="hidden" name="csrf" value="{esc(csrf)}"><button>Abmelden</button></form>' if user else '<a href="/login">Anmelden</a><a class="button" href="/register">Konto erstellen</a>'
    return f'<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · AG News</title><style>{STYLE}</style></head><body><header><div class="bar"><a class="brand" href="/"><b>AG</b>News</a><nav><a href="/">Übersicht</a><a href="/rss.xml">RSS ↗</a>{account}</nav></div></header><main>{content}</main><footer>AG News · Dein Überblick über IT & Sicherheit<br>Automatischer Quellenüberblick. Meldungen anhand der Originalquelle prüfen. Impressum und Datenschutz vor öffentlicher Freischaltung ergänzen.</footer></body></html>'
